<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateAttributes;

/**
 * @template-extends ArrayIterator<int, TemplateAttributes>
 */
class TemplateAttributesSlide extends ArrayIterator
{
    public function __construct(
        private readonly ?TemplateCursor $cursor,
        private readonly array $values
    ) {
        parent::__construct($values);
    }
    public function cursor(): ?TemplateCursor
    {
        return $this->cursor;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?TemplateAttributes
    {
        return parent::current();
    }
}
